def normalize_row(row, row_number):
    learner_id = row.get('learner_id', '').strip()
    lesson_id = row.get('lesson_id', '').strip()
    if not learner_id or not lesson_id:
        return None, {'row': row_number, 'error': 'missing_required_id'}
    return {'learner_id': learner_id, 'lesson_id': lesson_id}, None

def process(rows):
    accepted, rejected = [], []
    for number, row in enumerate(rows, start=2):
        clean, error = normalize_row(row, number)
        if error:
            rejected.append(error)
        else:
            accepted.append(clean)
    return {'accepted': accepted, 'rejected': rejected}

rows = [{'learner_id': ' ana ', 'lesson_id': ' loops '}, {'learner_id': '', 'lesson_id': 'functions'}]
print(process(rows))

