def clean_progress(row, row_number):
    learner_id = row.get('learner_id', '').strip()
    lesson_id = row.get('lesson_id', '').strip()
    if not learner_id or not lesson_id:
        return None, {'row': row_number, 'error': 'missing_required_id'}
    return {'learner_id': learner_id, 'lesson_id': lesson_id}, None

accepted, rejected = [], []
for number, row in enumerate(rows, start=2):
    record, error = clean_progress(row, number)
    (rejected if error else accepted).append(error or record)

assert accepted == [{'learner_id': 'sam', 'lesson_id': 'lists'}]
assert rejected == [{'row': 3, 'error': 'missing_required_id'}]
